<section class="container narrow section"><h1><?= ($mode ?? 'request') === 'confirm' ? 'Reset password' : 'Forgot your password?' ?></h1><div class="card"><?php if (($mode ?? 'request') === 'confirm'): ?><?php if (!empty($valid)): ?><form action="/reset-password/confirm" method="post" class="stack-form"><?= \App\Util\Csrf::field() ?><input type="hidden" name="token" value="<?= e($token ?? '') ?>"><label>New password <input type="password" name="password" required></label><button class="button" type="submit">Save new password</button></form><?php else: ?><p>This reset link is invalid or expired.</p><?php endif; ?><?php else: ?><form action="/reset-password" method="post" class="stack-form"><?= \App\Util\Csrf::field() ?><label>Email address <input type="email" name="email" required></label><button class="button" type="submit">Send reset link</button></form><?php endif; ?></div></section>
